options.getOption:
// Mean score of the chosen indicator by country, in the map's colours: each
// bar takes the colour the map gives a basin with that score, so the chart
// reads against the map's legend.
//
// Clicking a bar adds that country to the `pais` variable, or takes it out if
// it is already in; taking out the last one goes back to All. The map filters
// on `pais` in the browser (a kepler filter, no new request); the units
// counter and the worst-20 table ask the service again. This chart does not
// filter itself: the countries not picked stay, in grey, as context.
//
// Two query frames: `B` (columns `country`, `mean`, `n`: the units the drawn
// area touches, or all) and `range` (columns `country`, `lo`, `hi`: each
// country's lowest and highest score, never cut by the area). The map's
// colour scale is a quantize over the lowest to the highest score it holds,
// that is over the countries it shows: `range` rebuilds the same breaks.
// @constants begin
const VAR = 'pais';
const COLORS = ['#00939C', '#6BB5B9', '#AAD7D9', '#F4B198', '#DF744E', '#C22E00'];
const MAX = 5;
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;

const frameOf = (refId) => context.panel.data.series.find((f) => f.refId === refId);
const col = (frame, name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const means = frameOf('B');
const ranges = frameOf('range');
// Largest on top: a category axis draws bottom up.
const order = col(means, 'country')
  .map((c, i) => ({ country: String(c), mean: Number(col(means, 'mean')[i]), n: Number(col(means, 'n')[i]) }))
  .sort((a, b) => a.mean - b.mean);
const keys = order.map((r) => r.country);
const lo = new Map(col(ranges, 'country').map((c, i) => [String(c), Number(col(ranges, 'lo')[i])]));
const hi = new Map(col(ranges, 'country').map((c, i) => [String(c), Number(col(ranges, 'hi')[i])]));

const picked = () => {
  const values = new URLSearchParams(location.getLocation().search).getAll('var-' + VAR);
  return values.length === 0 || values.includes('$__all') || values.includes('All') ? null : values;
};
const toggle = (key) => {
  const now = picked();
  const next = !now ? [key] : now.includes(key) ? now.filter((v) => v !== key) : [...now, key];
  location.partial({ ['var-' + VAR]: next.length ? next : '$__all' }, true);
};

chart.off('click');
chart.on('click', (event) => toggle(keys[event.dataIndex]));

// The map's breaks: equal steps between the lowest and highest score of the
// countries it shows.
const scale = (chosen) => {
  const shown = [...lo.keys()].filter((c) => !chosen || chosen.includes(c));
  const min = Math.min(...shown.map((c) => lo.get(c)));
  const max = Math.max(...shown.map((c) => hi.get(c)));
  return (v) => {
    if (!Number.isFinite(min) || !(max > min)) {
      return COLORS[COLORS.length - 1];
    }
    const i = Math.floor(((v - min) / (max - min)) * COLORS.length);
    return COLORS[Math.max(0, Math.min(COLORS.length - 1, i))];
  };
};
const bars = (chosen) => {
  const color = scale(chosen);
  return order.map((r) => ({
    value: r.mean,
    itemStyle: {
      color: chosen && !chosen.includes(r.country) ? 'rgba(128, 128, 128, 0.22)' : color(r.mean),
      borderRadius: [0, 3, 3, 0],
    },
  }));
};

// A click changes the variable but not this query, so the panel is not drawn
// again: repaint the bars from the URL whenever it changes.
let drawn = JSON.stringify(picked());
const stop = location.getHistory().listen(() => {
  const now = picked();
  if (JSON.stringify(now) !== drawn && !chart.isDisposed()) {
    drawn = JSON.stringify(now);
    chart.setOption({ series: [{ id: 'bars', data: bars(now) }] });
  }
});

const option = {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 36, top: 8, bottom: 22, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const r = order[items[0].dataIndex];
      return `<b>${r.country}</b><br/>Mean score: <b>${r.mean.toFixed(2)}</b> of ${MAX}<br/>${r.n} units<br/><span style="opacity:.7">click to filter</span>`;
    },
  },
  xAxis: {
    type: 'value',
    min: 0,
    max: MAX,
    name: 'mean score (0–5)',
    nameLocation: 'middle',
    nameGap: 22,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: { type: 'category', data: keys, axisTick: { show: false }, axisLabel: { color: text, fontSize: 11 } },
  series: [
    {
      id: 'bars',
      type: 'bar',
      barWidth: '70%',
      barMaxWidth: 24,
      cursor: 'pointer',
      data: bars(picked()),
      label: { show: true, position: 'right', color: muted, fontSize: 11, formatter: (p) => p.value.toFixed(2) },
    },
  ],
};

return { version: 2, option, unsubscribe: stop };

